def is_palindrome(text):
    if text == "":
        return False

    reversed_text = text[::-1]
    return text == reversed_text

def filter_palindromes(words):
    palindromes = []
    for word in words:
        if is_palindrome(word):
            palindromes.append(word)
    return palindromes

words = ["level", "ab", "radar", ""]
result = filter_palindromes(words)
print(result)

